import numpy as np
def perp(v):
    a=np.array([1,0,0]) if abs(v[0])<0.9 else np.array([0,1,0])
    u=np.cross(v,a);u/=np.linalg.norm(u);w=np.cross(v,u);return u,w
def tet(c,d,L,n=3,phase=0):
    # substituents on c tetrahedral away from direction d (unit, points from c to parent)
    u,w=perp(-d);out=[]
    for k in range(n):
        t=phase+2*np.pi*k/n
        v=-d*np.cos(np.radians(180-109.47))*-1
        v=(-d)*0.3338+0.9426*(np.cos(t)*u+np.sin(t)*w)
        out.append(c+L*v/np.linalg.norm(v))
    return out
at=[('Ni',np.zeros(3))]
for s in [1,-1]:
    si=np.array([0,0,2.28*s]);at.append(('Si',si))
    for f in tet(si,np.array([0,0,-s]),1.60):at.append(('F',f))
for k in range(3):
    t=2*np.pi*k/3;d=np.array([np.cos(t),np.sin(t),0]);p=2.22*d;at.append(('P',p))
    for c in tet(p,-d,1.83,phase=np.pi/6):
        at.append(('C',c));dc=(p-c)/np.linalg.norm(p-c)
        for h in tet(c,dc,1.09,phase=0.3):at.append(('H',h))
with open('init.xyz','w') as f:
    f.write(f"{len(at)}\nNi(SiF3)2(PMe3)3\n")
    for e,x in at:f.write(f"{e} {x[0]:.4f} {x[1]:.4f} {x[2]:.4f}\n")
